#!/usr/bin/env node

// ────────────────────────────────────────────────────────────────
// DO NOT EDIT THIS FILE.
//
// COPY of source-of-truth at
//   ~/.claude/standards/scripts/verify/verify-commit-stamp.mjs
//
// Local edits will be overwritten the next time
//   bash ~/.claude/standards/scripts/install-slice-gates.sh
// runs. Edit the ORIGINAL and re-install.
// ────────────────────────────────────────────────────────────────
/**
 * verify-commit-stamp — SHIM. The pre-commit fresh-stamp gate is referenced by
 * EXACT NAME (CLAUDE.md pre-action rules + install-slice-gates.sh, which copies
 * this file universally into every repo's .git/hooks/pre-commit path). Its logic
 * now lives in verify-stamps.mjs; this delegates to that gate's commit-stamp
 * sub-check, passing through argv + stdout/stderr + exit code unchanged.
 *
 * Usage (unchanged): node scripts/verify/verify-commit-stamp.mjs
 *   Honors WEB_SUBDIR + derives the repo root from cwd, exactly as before.
 */
import { spawnSync } from "node:child_process";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const r = spawnSync(
  process.execPath,
  [join(HERE, "verify-stamps.mjs"), "--check", "commit-stamp", ...process.argv.slice(2)],
  { stdio: "inherit" },
);
process.exit(r.status ?? 1);
